        "title": "Optimal and Model Predictive Control",
        "credits": 6,
        "term": "SS",
        "termString": "Jedes Sommersemester",
        "duration": "1 Semester",
        "language": "English",
        "grading": "Zehntelnoten",
        "coordinators": [
          "Prof. Dr.-Ing. Thomas Meurer"
        ],
