        "id": "M-MATH-102909",
        "title": "Mathematische Statistik",
        "credits": 8,
        "term": "WS",
        "termString": "Jedes Wintersemester Pflichtbestandteile T-MATH-105872 Mathematische Statistik Dauer 1 Semester",
        "duration": "1 Semester",
