        "id": "M-ETIT-107497",
        "title": "Optimal Control",
        "credits": 6,
        "term": "WS",
        "termString": "Jedes Wintersemester",
        "duration": "1 Semester",
        "language": "English",
        "grading": "Zehntelnoten",
